mapper.select:
select  from nad_university


        and (name like concat('%', #{q}, '%')
             or name_cn like concat('%', #{q}, '%')
             or city like concat('%', #{q}, '%'))

    and country = #{country}
    and province = #{province}
    and city = #{city}
    and type = #{type}
    and is_featured = #{featured}
    and is_recommended = #{recommended}
    and status = #{status}
    and publish_status = #{publishStatus}

order by is_featured desc, is_recommended desc, name asc, id asc

select id, university_id, source, rank_position, rank_year, note
from nad_university_ranking where university_id = #{universityId}
order by rank_year desc, rank_position asc, id asc

select id, university_id, kind, sort_order, text
from nad_university_highlight where university_id = #{universityId}
order by kind asc, sort_order asc, id asc
